package com.ute.uteexpress.operations;

import com.ute.uteexpress.dto.operations.*;
import com.ute.uteexpress.dto.operations.CustomerTicketViews.Filter;
import com.ute.uteexpress.entity.*;
import com.ute.uteexpress.enums.*;
import com.ute.uteexpress.service.operations.OperationsRuleException;
import jakarta.validation.ConstraintViolationException;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import org.springframework.web.server.ResponseStatusException;
import com.ute.uteexpress.service.notifications.NotificationService;
import static com.ute.uteexpress.operations.OperationsJdbcFixture.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real JPA/JDBC on isolated H2, including method security and validation; no SQL Server claims. */
@SpringJUnitConfig(OperationsJdbcConfig.class)
class CustomerSupportJdbcTests extends CustomerSupportJdbcSupport {
    @Autowired NotificationService inbox;
    @Test void createsCustomerRootAndActorAuditWithoutChangingShipmentOrFees(){
        var before=db(()->em.find(Shipment.class,shipment.getId()).getTotalFee());Long id=createCustomer();
        db(()->{var t=em.find(SupportTicket.class,id);assertEquals(f.owner.getId(),t.getUser().getId());assertEquals(f.owner.getId(),t.getCreatedBy().getId());assertEquals(TicketSource.CUSTOMER,t.getSource());assertEquals(f.source.getId(),t.getHandlingBranch().getId());assertEquals(TicketStatus.OPEN,t.getStatus());assertEquals(TicketPriority.MEDIUM,t.getPriority());assertNull(t.getAssignedManager());assertEquals(NOW.plusHours(24),t.getWarningDueAt());var e=em.find(SupportTicketEvent.class,event(id,TicketAction.CREATED));assertEquals(f.owner.getId(),e.getActor().getId());var s=em.find(Shipment.class,shipment.getId());assertEquals(ShipmentStatus.CREATED,s.getStatus());assertEquals(before,s.getTotalFee());return null;});assertEquals(0,notices.count());
    }
    @Test void creationBecomesVisibleToResponsibleManagerAndOperationsQueue(){Long id=createCustomer();as(f.manager,"ROLE_MANAGER");var view=read.detail(id,0,0,0);assertEquals(TicketSource.CUSTOMER,view.source());assertTrue(read.list(f.source.getId(),TicketStatus.OPEN,null,null,null,true,false,0,20,"createdAt").stream().anyMatch(t->t.id().equals(id)));assertEquals(1L,dashboard.read(f.source.getId(),OperationsDashboardViews.Period.TODAY,null,null,null,OperationsDashboardViews.WorkGroup.CONFIRM,0).openUnassignedTickets());}
    @Test void otherOwnerAndUnknownShipmentHaveIdenticalMissingResponse(){as(f.other,"ROLE_USER");var a=assertThrows(ResponseStatusException.class,()->tickets.createCustomer(createCommand()));var b=assertThrows(ResponseStatusException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(999999L,TicketCategory.OTHER,"Valid","Valid",token())));assertEquals(HttpStatus.NOT_FOUND,a.getStatusCode());assertEquals(a.getReason(),b.getReason());assertEquals(0,ticketRows.count());}
    @ParameterizedTest @EnumSource(value=UserStatus.class,names={"LOCKED","UNVERIFIED"})
    void disabledAccountCannotCreateOrRead(UserStatus status){db(()->{em.find(User.class,f.owner.getId()).setStatus(status);return null;});assertThrows(AccessDeniedException.class,this::createCustomer);assertThrows(AccessDeniedException.class,()->customer.list(Filter.ALL,0,20));}
    @Test void freshDatabaseRoleIsRequiredDespiteSessionAuthority(){db(()->{em.createQuery("delete from UserRole r where r.user.id=:id").setParameter("id",f.owner.getId()).executeUpdate();return null;});assertThrows(AccessDeniedException.class,this::createCustomer);assertThrows(AccessDeniedException.class,()->customer.shipmentOptions(0));}
    @ParameterizedTest @ValueSource(strings={"ADMIN","MANAGER","SHIPPER"})
    void otherRolesCannotUseCustomerService(String role){as(f.owner,"ROLE_"+role);assertThrows(AccessDeniedException.class,this::createCustomer);assertThrows(AccessDeniedException.class,()->customer.list(Filter.ALL,0,20));}
    @ParameterizedTest @NullAndEmptySource @ValueSource(strings={" ","\t\n"})
    void blankSubjectRejectedAtService(String subject){assertThrows(ConstraintViolationException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(shipment.getId(),TicketCategory.DELAY,subject,"Content",token())));assertEquals(0,ticketRows.count());}
    @ParameterizedTest @ValueSource(ints={0,2001})
    void emptyOrOversizeDescriptionRejected(int size){assertThrows(ConstraintViolationException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(shipment.getId(),TicketCategory.DELAY,"Subject","x".repeat(size),token())));}
    @Test void oversizedSubjectNullCategoryAndMalformedTokenRejected(){assertThrows(ConstraintViolationException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(shipment.getId(),TicketCategory.DELAY,"x".repeat(201),"Content",token())));assertThrows(ConstraintViolationException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(shipment.getId(),null,"Subject","Content",token())));assertThrows(ConstraintViolationException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(shipment.getId(),TicketCategory.DELAY,"Subject","Content","forged")));}
    @Test void missingRouteFailsWithoutGuessingOriginBranch(){db(()->{em.createQuery("delete from SupportTicketRoute").executeUpdate();return null;});assertThrows(OperationsRuleException.class,this::createCustomer);assertEquals(0,ticketRows.count());}
    @Test void inactiveRouteFailsClosed(){db(()->{em.createQuery("update SupportTicketRoute r set r.active=false").executeUpdate();return null;});assertThrows(OperationsRuleException.class,this::createCustomer);}
    @Test void explicitDestinationRoutingIsUsedInsteadOfOriginGuess(){db(()->{em.createQuery("update SupportTicketRoute r set r.handlingBranch=:branch").setParameter("branch",em.find(Branch.class,f.destination.getId())).executeUpdate();return null;});Long id=createCustomer();assertEquals(f.destination.getId(),ticketRows.findById(id).orElseThrow().getHandlingBranch().getId());as(f.manager,"ROLE_MANAGER");assertThrows(ResponseStatusException.class,()->read.detail(id,0,0,0));as(f.destinationManager,"ROLE_MANAGER");assertNotNull(read.detail(id,0,0,0));}
    @Test void unrelatedRoutingBranchIsRejected(){db(()->{em.createQuery("update SupportTicketRoute r set r.handlingBranch=:branch").setParameter("branch",em.find(Branch.class,f.foreign.getId())).executeUpdate();return null;});assertThrows(OperationsRuleException.class,this::createCustomer);}
    @Test void inactiveConfiguredBranchIsRejected(){db(()->{em.find(Branch.class,f.source.getId()).setStatus(BranchStatus.INACTIVE);return null;});assertThrows(OperationsRuleException.class,this::createCustomer);}
    @Test void createReplayReturnsOriginalAndDifferentPayloadIsRejected(){var c=createCommand();Long id=tickets.createCustomer(c);assertEquals(id,tickets.createCustomer(c));assertThrows(OperationsRuleException.class,()->tickets.createCustomer(new CustomerTicketCommands.Create(c.shipmentId(),c.category(),"Different",c.content(),c.token())));assertEquals(1,ticketRows.count());assertEquals(1,eventRows.count());}
    @Test void customerCreateReplayUsesImmutableFingerprintAfterManagerChangesClassification(){var c=createCommand();Long id=tickets.createCustomer(c);as(f.manager,"ROLE_MANAGER");tickets.classify(id,new TicketCommands.Classify(version(id),TicketCategory.OTHER,TicketPriority.HIGH,"Phân loại lại"));as(f.owner,"ROLE_USER");assertEquals(id,tickets.createCustomer(c));assertEquals(1,ticketRows.count());}
    @Test void newTokenAllowsSeparateIssueEvenAfterAClosedTicket(){Long id=createCustomer();state(id,TicketStatus.CLOSED);assertNotEquals(id,createCustomer());assertEquals(2,ticketRows.count());}
    @Test void onlyOwnerReadsPostsOrRequestsReopenEvenKnowingCodes(){Long id=createCustomer();var c=message(id,"Attempt");as(f.other,"ROLE_USER");assertEquals(0,customer.list(Filter.ALL,0,20).getTotalElements());assertThrows(ResponseStatusException.class,()->customer.portalDetail(id,0));assertThrows(ResponseStatusException.class,()->tickets.customerMessage(id,c));assertThrows(ResponseStatusException.class,()->tickets.requestCustomerReopen(id,c));}
    @Test void manualManagerIntakeHidesInternalContentAndNeverUsesResolutionNotesDirectly(){as(f.manager,"ROLE_MANAGER");Long id=tickets.create(command(shipment));tickets.note(id,new TicketCommands.Message(version(id),"INTERNAL INVESTIGATION"));tickets.reply(id,new TicketCommands.Message(version(id),"Public reply"));as(f.owner,"ROLE_USER");var view=customer.portalDetail(id,0);assertNull(view.initialContent());assertEquals(1,view.messages().getTotalElements());assertEquals("Public reply",view.messages().getContent().getFirst().body());assertFalse(view.toString().contains("INTERNAL INVESTIGATION"));assertFalse(view.toString().contains("Nội dung tiếp nhận nội bộ"));assertNull(view.resolution());}
    @Test void mismatchedRequesterAndLegacyUnscopedRecordsNeverGainAccess(){Long id=createCustomer();db(()->{em.find(SupportTicket.class,id).setUser(em.find(User.class,f.other.getId()));SupportTicket old=new SupportTicket();old.setTicketCode("LEGACY");old.setUser(f.owner);old.setShipment(shipment);old.setSubject("Legacy");old.setContent("Not verified");em.persist(old);return null;});assertEquals(0,customer.list(Filter.ALL,0,20).getTotalElements());assertThrows(ResponseStatusException.class,()->customer.portalDetail(id,0));as(f.other,"ROLE_USER");assertThrows(ResponseStatusException.class,()->customer.portalDetail(id,0));}
    @Test void publicConversationHasStableOldestFirstOrderAndNoStaffIdentity(){Long id=createCustomer();tickets.customerMessage(id,message(id,"One"));as(f.manager,"ROLE_MANAGER");tickets.note(id,new TicketCommands.Message(version(id),"INTERNAL"));tickets.reply(id,new TicketCommands.Message(version(id),"Two"));as(f.owner,"ROLE_USER");tickets.customerMessage(id,message(id,"Three"));var view=customer.portalDetail(id,0);assertEquals(List.of("One","Two","Three"),view.messages().map(CustomerTicketViews.Message::body).getContent());assertTrue(view.messages().getContent().getFirst().customer());assertFalse(view.messages().getContent().get(1).customer());assertFalse(view.toString().contains(f.manager.getEmail()));}
    @Test void conversationPaginationDoesNotSkipSameTimestampMessagesOrInternalRows(){Long id=createCustomer();for(int i=0;i<25;i++)tickets.customerMessage(id,message(id,"Message "+i));as(f.manager,"ROLE_MANAGER");tickets.note(id,new TicketCommands.Message(version(id),"INTERNAL PAGE ROW"));as(f.owner,"ROLE_USER");var first=customer.portalDetail(id,0).messages();var second=customer.portalDetail(id,1).messages();assertEquals(25,first.getTotalElements());assertEquals(20,first.getNumberOfElements());assertEquals(5,second.getNumberOfElements());assertEquals("Message 0",first.getContent().getFirst().body());assertEquals("Message 24",second.getContent().getLast().body());assertFalse(second.toString().contains("INTERNAL PAGE ROW"));}
    @Test void paginationBoundsAndServerOwnershipApplyToBothLists(){for(int i=0;i<3;i++)createCustomer();assertEquals(2,customer.list(Filter.ALL,0,2).getNumberOfElements());assertEquals(1,customer.list(Filter.ALL,1,2).getNumberOfElements());assertTrue(customer.list(Filter.ALL,0,2).getContent().get(0).id()>customer.list(Filter.ALL,0,2).getContent().get(1).id());assertThrows(OperationsRuleException.class,()->customer.list(Filter.ALL,-1,20));assertThrows(OperationsRuleException.class,()->customer.list(Filter.ALL,0,51));assertThrows(OperationsRuleException.class,()->customer.portalDetail(1L,-1));as(f.other,"ROLE_USER");assertEquals(0,customer.shipmentOptions(0).getTotalElements());assertThrows(ResponseStatusException.class,()->customer.shipment(shipment.getId()));}
    @Test void filtersDistinguishWaitingResolvedClosedAndWorking(){Long open=createCustomer(),waiting=createCustomer(),resolved=createCustomer(),closed=createCustomer();state(waiting,TicketStatus.WAITING_CUSTOMER);state(resolved,TicketStatus.RESOLVED);state(closed,TicketStatus.CLOSED);assertEquals(open,customer.list(Filter.WORKING,0,20).getContent().getFirst().id());assertEquals(waiting,customer.list(Filter.WAITING_CUSTOMER,0,20).getContent().getFirst().id());assertEquals(resolved,customer.list(Filter.RESOLVED,0,20).getContent().getFirst().id());assertEquals(closed,customer.list(Filter.CLOSED,0,20).getContent().getFirst().id());}
    @ParameterizedTest @EnumSource(TicketStatus.class)
    void messagesRespectActualLifecycleAndNeverAutoTransition(TicketStatus status){Long id=createCustomer();state(id,status);var c=message(id,"Customer text");long count=messageRows.count();if(status==TicketStatus.RESOLVED || status==TicketStatus.CLOSED){assertThrows(OperationsRuleException.class,()->tickets.customerMessage(id,c));assertEquals(count,messageRows.count());}else{tickets.customerMessage(id,c);assertEquals(count+1,messageRows.count());db(()->{var e=em.find(SupportTicketEvent.class,event(id,TicketAction.CUSTOMER_MESSAGE));assertEquals(f.owner.getId(),e.getActor().getId());assertEquals(TicketMessageKind.PUBLIC,e.getMessage().getKind());return null;});}assertEquals(status,ticketRows.findById(id).orElseThrow().getStatus());}
    @ParameterizedTest @NullAndEmptySource @ValueSource(strings={" ","\n\t"})
    void blankMessagesAreRejected(String body){Long id=createCustomer();assertThrows(ConstraintViolationException.class,()->tickets.customerMessage(id,new CustomerTicketCommands.Message(version(id),body,token())));assertEquals(0,messageRows.count());}
    @Test void oversizedMessageAndMissingVersionAreRejected(){Long id=createCustomer();assertThrows(ConstraintViolationException.class,()->tickets.customerMessage(id,new CustomerTicketCommands.Message(version(id),"x".repeat(2001),token())));assertThrows(ConstraintViolationException.class,()->tickets.customerMessage(id,new CustomerTicketCommands.Message(null,"Body",token())));}
    @Test void staleMessageVersionIsConflictInsteadOfLastWriteWins(){Long id=createCustomer();var stale=message(id,"Stale");tickets.customerMessage(id,message(id,"First"));assertThrows(ObjectOptimisticLockingFailureException.class,()->tickets.customerMessage(id,stale));assertEquals(1,messageRows.count());}
    @Test void messageRetryIsIdempotentEvenAfterManagerTransition(){Long id=createCustomer();var c=message(id,"Original");tickets.customerMessage(id,c);state(id,TicketStatus.CLOSED);tickets.customerMessage(id,c);assertEquals(2,messageRows.count());assertThrows(OperationsRuleException.class,()->tickets.customerMessage(id,new CustomerTicketCommands.Message(c.version(),"Changed",c.token())));}
    @Test void messageTokenCannotBeReusedOnAnotherTicketOrForReopenAction(){Long id=createCustomer(),other=createCustomer();var c=message(id,"Once");tickets.customerMessage(id,c);assertThrows(OperationsRuleException.class,()->tickets.customerMessage(other,new CustomerTicketCommands.Message(version(other),c.body(),c.token())));state(id,TicketStatus.CLOSED);assertThrows(OperationsRuleException.class,()->tickets.requestCustomerReopen(id,new CustomerTicketCommands.Message(version(id),c.body(),c.token())));assertEquals(2,messageRows.count());}
    @Test void resolvedResultComesFromExplicitPublicResolutionMessage(){Long id=createCustomer();state(id,TicketStatus.RESOLVED);var view=customer.portalDetail(id,0);assertEquals("Kết quả công khai chính thức",view.resolution().body());db(()->{em.find(SupportTicket.class,id).setResolutionNotes("INTERNAL REPLACEMENT NOT PUBLIC");return null;});assertFalse(customer.portalDetail(id,0).toString().contains("INTERNAL REPLACEMENT"));}
    @ParameterizedTest @EnumSource(value=TicketStatus.class,names={"RESOLVED","CLOSED"})
    void reopenRequestPreservesStateAndHasOnePendingRequestPerResolutionCycle(TicketStatus status){Long id=createCustomer();state(id,status);var c=message(id,"Kết quả chưa phù hợp");tickets.requestCustomerReopen(id,c);tickets.requestCustomerReopen(id,c);assertEquals(status,ticketRows.findById(id).orElseThrow().getStatus());assertTrue(customer.portalDetail(id,0).reopenPending());assertFalse(customer.portalDetail(id,0).canRequestReopen());assertEquals(1,eventRows.pendingReopenRequests(id));assertThrows(OperationsRuleException.class,()->tickets.requestCustomerReopen(id,message(id,"More")));as(f.manager,"ROLE_MANAGER");tickets.reopen(id,new TicketCommands.Decision(version(id),"Đồng ý xem xét"));assertEquals(0,eventRows.pendingReopenRequests(id));assertEquals(TicketStatus.REOPENED,ticketRows.findById(id).orElseThrow().getStatus());}
    @Test void reopenRequestNeedsReasonAndCannotBeUsedOnWorkingTicket(){Long id=createCustomer();assertThrows(OperationsRuleException.class,()->tickets.requestCustomerReopen(id,message(id,"Why")));state(id,TicketStatus.CLOSED);assertThrows(ConstraintViolationException.class,()->tickets.requestCustomerReopen(id,new CustomerTicketCommands.Message(version(id)," ",token())));}
    @Test void newCustomerTicketNotifiesOnlyEligibleManagersOfConfiguredBranchAfterCommit(){Long id=createCustomer();Long source=event(id,TicketAction.CREATED);assertEquals(0,notices.count());notifications.process(source);notifications.process(source);assertEquals(2,notices.count());assertEquals(Set.of(f.manager.getId(),f.secondManager.getId()),notices.findAll().stream().map(n->n.getUser().getId()).collect(java.util.stream.Collectors.toSet()));assertEquals(0,notices.unreadCount(f.destinationManager.getId()));assertEquals(0,notices.unreadCount(f.outsider.getId()));}
    @Test void customerMessageNotifiesCurrentValidAssigneeWithNoBodyInPayload(){Long id=createCustomer();state(id,TicketStatus.PROCESSING);tickets.customerMessage(id,message(id,"PRIVATE CUSTOMER MESSAGE"));notifications.process(event(id,TicketAction.CUSTOMER_MESSAGE));assertEquals(1,notices.count());var n=notices.findAll().getFirst();assertEquals(f.secondManager.getId(),n.getUser().getId());assertFalse(n.getMessage().contains("PRIVATE CUSTOMER MESSAGE"));as(f.secondManager,"ROLE_MANAGER");assertEquals("/manager/tickets/"+id,inbox.target(n.getId()));assertEquals("PRIVATE CUSTOMER MESSAGE",read.detail(id,0,0,0).messages().getContent().getFirst().body());}
    @Test void revokedAssigneeFallsBackToEligibleBranchManagers(){Long id=createCustomer();state(id,TicketStatus.PROCESSING);tickets.customerMessage(id,message(id,"Message"));db(()->{em.find(Employee.class,f.secondEmployee.getId()).setStatus(EmployeeStatus.INACTIVE);return null;});notifications.process(event(id,TicketAction.CUSTOMER_MESSAGE));assertEquals(1,notices.count());assertEquals(f.manager.getId(),notices.findAll().getFirst().getUser().getId());}
    @Test void publicReplyResolutionAndImportantStatusNoticesLinkToCustomerPortalAndRecheckOwnership(){Long id=createCustomer();state(id,TicketStatus.WAITING_CUSTOMER);notifications.process(event(id,TicketAction.STATUS_CHANGED));as(f.manager,"ROLE_MANAGER");tickets.reply(id,new TicketCommands.Message(version(id),"PUBLIC BODY"));notifications.process(event(id,TicketAction.PUBLIC_REPLY));tickets.resolve(id,new TicketCommands.Decision(version(id),"PUBLIC RESULT"));notifications.process(event(id,TicketAction.RESOLVED));tickets.close(id,new TicketCommands.Decision(version(id),"Internal closing reason"));notifications.process(event(id,TicketAction.CLOSED));as(f.owner,"ROLE_USER");assertEquals(4,inbox.count());var n=notices.findAll().getFirst();assertEquals("/account/support/"+id,inbox.target(n.getId()));assertFalse(inbox.list(0,20,false).toString().contains("PUBLIC BODY"));db(()->{em.find(Shipment.class,shipment.getId()).setSender(em.find(User.class,f.other.getId()));return null;});assertEquals(0,inbox.count());assertThrows(ResponseStatusException.class,()->inbox.target(n.getId()));assertThrows(ResponseStatusException.class,()->customer.portalDetail(id,0));}
    @Test void reopenRequestNotifiesAssignedManagerButNeverCustomerAsIfAlreadyReopened(){Long id=createCustomer();state(id,TicketStatus.CLOSED);tickets.requestCustomerReopen(id,message(id,"Please review"));Long event=event(id,TicketAction.REOPEN_REQUESTED);notifications.process(event);notifications.process(event);assertEquals(1,notices.count());assertEquals(f.secondManager.getId(),notices.findAll().getFirst().getUser().getId());assertEquals(0,notices.unreadCount(f.owner.getId()));}
}
